mapper.insert:
INSERT INTO diary_cover_library_reports (
    library_item_id, reported_snapshot_version, photo_asset_id,
    reporter_user_id, reason_code, description, status
) VALUES (
    #{libraryItemId}, #{reportedSnapshotVersion}, #{photoAssetId},
    #{reporterUserId}, #{reasonCode}, #{description}, #{status}
)

mapper.select:
SELECT COUNT(*)
FROM diary_cover_library_reports

    WHERE status = #{status}

SELECT r.id AS report_id, r.library_item_id, r.reported_snapshot_version, r.photo_asset_id, i.title AS library_title, i.creator_display_name, r.reason_code, COALESCE(NULLIF(u.nickname, ''), '탈퇴한 사용자') AS reporter_display_name, r.status, r.created_at FROM diary_cover_library_reports r JOIN diary_cover_library_items i ON i.id = r.library_item_id LEFT JOIN users u ON u.id = r.reporter_user_id
WHERE r.status = #{status}
ORDER BY r.created_at DESC, r.id DESC LIMIT #{limit} OFFSET #{offset}
